const listPaystubs = `-- name: ListPaystubs :many
SELECT
    p.id, p.user_id, p.employer_id, p.period_start, p.period_end, p.pay_date, p.gross, p.net, p.ytd_gross, p.ytd_net, p.source, p.confirmed_at, p.is_shared, p.transaction_id, p.document_id, p.created_at, p.updated_at,
    e.name          AS employer_name,
    e.pay_frequency AS pay_frequency,
    -- The linked deposit, so the list can show the reconciliation state without
    -- a second round trip per row.
    t.date          AS deposit_date,
    t.amount        AS deposit_amount
FROM paystubs p
JOIN employers e ON e.id = p.employer_id
JOIN users     u ON u.id = p.user_id
LEFT JOIN transactions t ON t.id = p.transaction_id
WHERE u.household_id = $1
  AND (p.user_id = $2 OR p.is_shared)
  AND (NOT $3::boolean
       OR EXTRACT(YEAR FROM p.pay_date) = $4::int)
ORDER BY p.pay_date DESC, p.created_at DESC
`

