// The paystub list and the review queue, in one query. Unconfirmed rows are
// included on purpose — reviewing them is the point — and every consumer that
// reports a FIGURE uses one of the ...ForYear queries below instead.
func (q *Queries) ListPaystubs(ctx context.Context, arg ListPaystubsParams) ([]ListPaystubsRow, error) {
	rows, err := q.db.Query(ctx, listPaystubs,
		arg.HouseholdID,
		arg.UserID,
		arg.ByYear,
		arg.TaxYear,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPaystubsRow{}
	for rows.Next() {
		var i ListPaystubsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.EmployerID,
			&i.PeriodStart,
			&i.PeriodEnd,
			&i.PayDate,
			&i.Gross,
			&i.Net,
			&i.YtdGross,
			&i.YtdNet,
			&i.Source,
			&i.ConfirmedAt,
			&i.IsShared,
			&i.TransactionID,
			&i.DocumentID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.EmployerName,
			&i.PayFrequency,
			&i.DepositDate,
			&i.DepositAmount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const matchDepositsForPaystub = `-- name: MatchDepositsForPaystub :many

SELECT
    t.id,
    t.date,
    t.amount,
    COALESCE(NULLIF(t.merchant_name, ''), t.name) AS label,
    a.name                                        AS account_name,
    -- Cast is load-bearing, not decoration: without it sqlc infers ABS() as an
    -- integer and the generated struct silently truncates every cent of the gap
    -- this column exists to report.
    ABS(-t.amount - $1::numeric)::numeric AS delta
FROM transactions t
JOIN accounts    a ON a.id = t.account_id
JOIN account_access v ON v.account_id = a.id
LEFT JOIN categories c ON c.id = t.category_id
WHERE v.household_id = $2
  AND (v.user_id = $3 OR v.is_shared)
  AND a.is_active
  AND NOT t.pending
  AND NOT t.excluded_from_reports
  AND NOT COALESCE(c.is_transfer, FALSE)
  AND t.amount < 0
  AND t.date >= $4
  AND t.date <= $5
  AND NOT EXISTS (
      SELECT 1 FROM paystubs claimed
      WHERE claimed.transaction_id = t.id
        AND claimed.id <> $6
  )
ORDER BY delta, ABS(t.date - $7::date), t.date DESC
LIMIT $8
`

type MatchDepositsForPaystubParams struct {
	Net         decimal.Decimal `json:"net"`
	HouseholdID uuid.UUID       `json:"household_id"`
	UserID      uuid.UUID       `json:"user_id"`
	FromDate    stdtime.Time    `json:"from_date"`
	ToDate      stdtime.Time    `json:"to_date"`
	PaystubID   uuid.UUID       `json:"paystub_id"`
	PayDate     stdtime.Time    `json:"pay_date"`
	MaxResults  int32           `json:"max_results"`
}

type MatchDepositsForPaystubRow struct {
	ID          uuid.UUID       `json:"id"`
	Date        stdtime.Time    `json:"date"`
	Amount      decimal.Decimal `json:"amount"`
	Label       string          `json:"label"`
	AccountName string          `json:"account_name"`
	Delta       decimal.Decimal `json:"delta"`
}

// --------------------------------------------------------------------------
// Deposit reconciliation
// --------------------------------------------------------------------------
// Candidate bank deposits for a stub's net pay. A PROPOSAL, always.
//
// Deliberately not an exact-amount match. A direct deposit split between
// checking and savings lands as two rows that each fall short of net, and an
// exact matcher would silently find nothing for a household that does something
// extremely ordinary. Ranking by closeness and letting a human choose covers
// that case and the identical-amounts case at once.
//
// The NOT EXISTS is what stops one deposit being claimed by two stubs — the
// two-earner household with equal take-home, which doc 23 names as the case
// that must not auto-match. It cannot even be OFFERED twice.
//
// Money-in is amount < 0 (Plaid's convention: positive is money leaving), and
// transfers are excluded because a paycheque is not one.
func (q *Queries) MatchDepositsForPaystub(ctx context.Context, arg MatchDepositsForPaystubParams) ([]MatchDepositsForPaystubRow, error) {
	rows, err := q.db.Query(ctx, matchDepositsForPaystub,
		arg.Net,
		arg.HouseholdID,
		arg.UserID,
		arg.FromDate,
		arg.ToDate,
		arg.PaystubID,
		arg.PayDate,
		arg.MaxResults,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MatchDepositsForPaystubRow{}
	for rows.Next() {
		var i MatchDepositsForPaystubRow
		if err := rows.Scan(
			&i.ID,
			&i.Date,
			&i.Amount,
			&i.Label,
			&i.AccountName,
			&i.Delta,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

